INSERT INTO questions (id, subject, syllabus_topic, question_text, options, correct_option_index, explanation) VALUES
  ('q_math_001', 'Mathematics', 'Algebra', 'If 2x + 5 = 17, what is the value of x?', ARRAY['5', '6', '7', '8'], 1, 'Subtract 5 from both sides to get 2x = 12, then divide by 2 to get x = 6.'),
  ('q_math_002', 'Mathematics', 'Algebra', 'Simplify: 3(x + 4) - 2x.', ARRAY['x + 12', 'x + 4', '5x + 12', '5x + 4'], 0, 'Multiply out 3(x + 4) to get 3x + 12, then subtract 2x to get x + 12.'),
  ('q_math_003', 'Mathematics', 'Algebra', 'Factorize completely: x^2 - 9.', ARRAY['(x - 3)(x - 3)', '(x + 3)(x + 3)', '(x + 3)(x - 3)', '(x + 9)(x - 1)'], 2, 'x^2 - 9 is a difference of two squares, which factorizes as (x + 3)(x - 3).'),
  ('q_math_004', 'Mathematics', 'Algebra', 'Solve the equation: x/3 = 7.', ARRAY['3', '10', '21', '24'], 2, 'Multiply both sides by 3 to get x = 21.'),
  ('q_math_005', 'Mathematics', 'Algebra', 'If a = 3 and b = 4, find the value of 2a + 3b.', ARRAY['12', '15', '17', '18'], 3, '2(3) + 3(4) = 6 + 12 = 18, so the correct answer is 18.'),
  ('q_math_006', 'Mathematics', 'Geometry', 'What is the area of a rectangle with length 8 cm and width 5 cm?', ARRAY['13 cm²', '26 cm²', '30 cm²', '40 cm²'], 3, 'Area = length × width = 8 × 5 = 40 cm².'),
  ('q_math_007', 'Mathematics', 'Geometry', 'The angles of a triangle are in the ratio 1:2:3. What is the smallest angle?', ARRAY['30°', '45°', '60°', '90°'], 0, 'The sum of angles in a triangle is 180°. 1+2+3 = 6 parts, so one part is 180°/6 = 30°. The smallest angle is 30°.'),
  ('q_math_008', 'Mathematics', 'Number', 'What is the HCF of 12 and 18?', ARRAY['2', '3', '6', '9'], 2, 'The highest common factor of 12 and 18 is 6, since 12 = 2²×3 and 18 = 2×3², and the common part is 2×3 = 6.'),
  ('q_math_009', 'Mathematics', 'Number', 'What is 15% of 200?', ARRAY['15', '20', '25', '30'], 3, '15% of 200 = (15/100) × 200 = 0.15 × 200 = 30.'),
  ('q_math_010', 'Mathematics', 'Number', 'What is the next term in the sequence: 2, 5, 8, 11, ...?', ARRAY['12', '13', '14', '15'], 2, 'The sequence increases by 3 each time. After 11, the next term is 11 + 3 = 14.'),
  ('q_eng_001', 'English Language', 'Comprehension', 'Choose the word that best completes the sentence: ''The teacher''s explanation was ______ useful to the students.''', ARRAY['very', 'the', 'a', 'an'], 0, 'The adverb ''very'' correctly qualifies the adjective ''useful'': ''very useful''.'),
  ('q_eng_002', 'English Language', 'Grammar', 'Choose the correct form: ''She ______ to the market every Saturday.''', ARRAY['go', 'goes', 'going', 'gone'], 1, 'The subject ''She'' is third person singular, and ''every Saturday'' is a habitual action, so the present simple ''goes'' is correct.'),
  ('q_eng_003', 'English Language', 'Grammar', 'Identify the correct sentence: ''He don''t know the answer.''', ARRAY['He don''t know the answer.', 'He doesn''t know the answer.', 'He not know the answer.', 'He no knows the answer.'], 1, '''Doesn''t'' is the correct negative form for a third person singular subject like ''He''.'),
  ('q_eng_004', 'English Language', 'Vocabulary', 'Choose the word that means the opposite of ''generous''.', ARRAY['kind', 'selfish', 'honest', 'loyal'], 1, '''Selfish'' means caring only about oneself, which is the opposite of ''generous'' meaning willing to give to others.'),
  ('q_eng_005', 'English Language', 'Comprehension', 'Choose the best word to complete: ''The noise from the construction site was ______.''', ARRAY['pleasant', 'loud', 'delicious', 'soft'], 1, 'Construction sites are typically noisy, so ''loud'' best describes the noise.'),
  ('q_eng_006', 'English Language', 'Vocabulary', 'Choose the correct word: ''The ______ barked at the stranger.''', ARRAY['cat', 'dog', 'bird', 'fish'], 1, 'Dogs typically bark at strangers; cats meow, birds chirp, and fish do not bark.'),
  ('q_eng_007', 'English Language', 'Grammar', 'Choose the correct form: ''I have been ______ for two hours.''', ARRAY['wait', 'waited', 'waiting', 'waits'], 2, 'The present perfect continuous tense requires ''have/has been + verb-ing'', so ''waiting'' is correct.'),
  ('q_eng_008', 'English Language', 'Comprehension', 'Choose the best word to complete: ''The ______ sun rose over the hills.''', ARRAY['bright', 'table', 'soft', 'heavy'], 0, '''Bright'' describes the sun positively and accurately in a sunrise context.'),
  ('q_eng_009', 'English Language', 'Grammar', 'Choose the correct sentence: ''She is taller than I.''', ARRAY['She is taller than I.', 'She is taller than me.', 'She is more taller than me.', 'She is taller than I am.'], 3, '''Than I'' or ''than I am'' is the formal comparative structure; ''more taller'' is doubly incorrect as ''taller'' is already comparative.'),
  ('q_eng_010', 'English Language', 'Vocabulary', 'Choose the synonym of ''happy''.', ARRAY['sad', 'angry', 'joyful', 'tired'], 2, '''Joyful'' means full of joy, which is a synonym of ''happy''.'),
  ('q_phys_001', 'Physics', 'Motion', 'What is the SI unit of speed?', ARRAY['Metre', 'Metre per second', 'Second', 'Kilogram'], 1, 'Speed is distance divided by time, so the SI unit is metre per second (m/s).'),
  ('q_phys_002', 'Physics', 'Motion', 'A car travels 120 m in 6 seconds. What is its speed?', ARRAY['10 m/s', '15 m/s', '20 m/s', '720 m/s'], 2, 'Speed = distance / time = 120 / 6 = 20 m/s.'),
  ('q_phys_003', 'Physics', 'Force', 'According to Newton''s Second Law, force equals:', ARRAY['mass × velocity', 'mass × acceleration', 'mass ÷ acceleration', 'pressure × area'], 1, 'Newton''s Second Law states F = m × a, where F is force, m is mass, and a is acceleration.'),
  ('q_phys_004', 'Physics', 'Energy', 'What form of energy does a moving object possess?', ARRAY['Potential energy', 'Kinetic energy', 'Heat energy', 'Sound energy'], 1, 'A moving object possesses kinetic energy, the energy of motion.'),
  ('q_phys_005', 'Physics', 'Waves', 'Which of the following is a longitudinal wave?', ARRAY['Light wave', 'Sound wave', 'Water wave', 'Radio wave'], 1, 'Sound waves are longitudinal, meaning the particles vibrate parallel to the direction of wave travel.'),
  ('q_chem_001', 'Chemistry', 'Atomic Structure', 'What is the atomic number of an oxygen atom?', ARRAY['6', '8', '16', '17'], 1, 'Oxygen has 8 protons, so its atomic number is 8.'),
  ('q_chem_002', 'Chemistry', 'Chemical Bonding', 'What type of bond forms between sodium and chlorine in NaCl?', ARRAY['Covalent bond', 'Ionic bond', 'Metallic bond', 'Hydrogen bond'], 1, 'Sodium donates an electron to chlorine, forming an ionic bond in sodium chloride.'),
  ('q_chem_003', 'Chemistry', 'Reactions', 'Which gas is produced when an acid reacts with a metal?', ARRAY['Oxygen', 'Hydrogen', 'Carbon dioxide', 'Nitrogen'], 1, 'Metals react with acids to produce hydrogen gas and a salt.'),
  ('q_chem_004', 'Chemistry', 'Periodic Table', 'Which group of the periodic table contains the noble gases?', ARRAY['Group 1', 'Group 2', 'Group 17', 'Group 18'], 3, 'Noble gases such as helium, neon, and argon are in Group 18 of the periodic table.'),
  ('q_chem_005', 'Chemistry', 'Formulae', 'What is the chemical formula for water?', ARRAY['H2O', 'CO2', 'NaCl', 'O2'], 0, 'Water consists of two hydrogen atoms and one oxygen atom, so its formula is H2O.'),
  ('q_bio_001', 'Biology', 'Cell Biology', 'Which organelle is known as the powerhouse of the cell?', ARRAY['Nucleus', 'Mitochondria', 'Ribosome', 'Cell membrane'], 1, 'Mitochondria are called the powerhouse of the cell because they generate ATP through respiration.'),
  ('q_bio_002', 'Biology', 'Photosynthesis', 'Which gas is absorbed by plants during photosynthesis?', ARRAY['Oxygen', 'Nitrogen', 'Carbon dioxide', 'Hydrogen'], 2, 'During photosynthesis, plants absorb carbon dioxide from the air to make glucose.'),
  ('q_bio_003', 'Biology', 'The Cell', 'What is the functional unit of the human nervous system?', ARRAY['Neuron', 'Muscle cell', 'Red blood cell', 'Bone cell'], 0, 'The neuron (nerve cell) is the basic functional unit of the nervous system.'),
  ('q_bio_004', 'Biology', 'Heredity', 'Who is known as the father of genetics?', ARRAY['Charles Darwin', 'Gregor Mendel', 'Louis Pasteur', 'Alexander Fleming'], 1, 'Gregor Mendel''s work with pea plants established the basic laws of inheritance, so he is called the father of genetics.'),
  ('q_bio_005', 'Biology', 'Ecology', 'What is a group of organisms of the same species living in a given area called?', ARRAY['Community', 'Population', 'Ecosystem', 'Biosphere'], 1, 'A population is a group of organisms of the same species living together in the same area at the same time.'),
  ('q_eco_001', 'Economics', 'Basic Concepts', 'What does ''scarcity'' mean in economics?', ARRAY['Unlimited wants with limited resources', 'Plenty of everything', 'No need for money', 'Free goods only'], 0, 'Scarcity means human wants are unlimited but the resources to satisfy them are limited.'),
  ('q_eco_002', 'Economics', 'Supply and Demand', 'When demand for a commodity increases and supply remains constant, the price tends to:', ARRAY['Fall', 'Rise', 'Stay the same', 'Double'], 1, 'Higher demand with unchanged supply pushes the price upward towards a new equilibrium.'),
  ('q_eco_003', 'Economics', 'Types of Goods', 'Which of the following is a capital good?', ARRAY['Milk', 'A tractor', 'A shirt', 'A loaf of bread'], 1, 'A capital good is a machine or tool used to produce other goods, such as a tractor on a farm.'),
  ('q_eco_004', 'Economics', 'Demand', 'What is the law of demand?', ARRAY['Price and quantity demanded move in the same direction', 'As price falls, quantity demanded rises', 'As price rises, quantity demanded rises', 'Demand never changes'], 1, 'The law of demand states that, ceteris paribus, a higher price leads to a smaller quantity demanded, and vice versa.'),
  ('q_eco_005', 'Economics', 'Money', 'Which of the following is a function of money?', ARRAY['It tastes delicious', 'It serves as a medium of exchange', 'It grows on trees', 'It is always free'], 1, 'One key function of money is to act as a medium of exchange, making trade easier than barter.'),
  ('q_geo_001', 'Geography', 'Map Work', 'What does a map scale show?', ARRAY['The colour of the map', 'The relationship between distance on the map and real distance on the ground', 'The size of the printer', 'The date the map was printed'], 1, 'A map scale shows how map distances relate to actual distances on the ground, for example 1 cm = 1 km.'),
  ('q_geo_002', 'Geography', 'Weather and Climate', 'Which instrument measures rainfall?', ARRAY['Thermometer', 'Rain gauge', 'Barometer', 'Wind vane'], 1, 'A rain gauge is used to measure the amount of rainfall at a weather station.'),
  ('q_geo_003', 'Geography', 'Africa', 'Which of these African rivers is the longest?', ARRAY['Niger', 'Congo', 'Nile', 'Zambezi'], 2, 'The Nile River is usually considered the longest river in Africa, flowing northwards through several countries.'),
  ('q_geo_004', 'Geography', 'Nigeria', 'What is the capital city of Nigeria?', ARRAY['Lagos', 'Abuja', 'Kano', 'Ibadan'], 1, 'Abuja has been the capital of Nigeria since 1991, replacing Lagos.'),
  ('q_geo_005', 'Geography', 'Climate', 'Which climate zone is associated with very low rainfall and extreme temperatures?', ARRAY['Rainforest', 'Desert', 'Temperate', 'Mediterranean'], 1, 'Desert climates are characterised by very low rainfall and large daily temperature ranges.'),
  ('q_gov_001', 'Government', 'Basic Concepts', 'What is the main purpose of government in a state?', ARRAY['To make laws and maintain order', 'To run all businesses', 'To collect all money', 'To choose all leaders by chance'], 0, 'A government makes laws, maintains order, and provides services for the well-being of its citizens.'),
  ('q_gov_002', 'Government', 'Types of Government', 'A system of government in which power is held by a small elite is called:', ARRAY['Democracy', 'Oligarchy', 'Monarchy', 'Anarchy'], 1, 'An oligarchy is a system in which a small group of people holds power, rather than the whole population.'),
  ('q_gov_003', 'Government', 'Constitution', 'What is a constitution?', ARRAY['A type of food', 'A set of fundamental rules and principles for governing a country', 'A history textbook', 'A foreign passport'], 1, 'A constitution is the supreme law of a country, setting out how the government is organised and the rights of citizens.'),
  ('q_gov_004', 'Government', 'Arms of Government', 'Which arm of government is responsible for making laws?', ARRAY['The Executive', 'The Legislature', 'The Judiciary', 'The Military'], 1, 'The legislature, such as Parliament, is the arm of government that makes laws.'),
  ('q_gov_005', 'Government', 'Democracy', 'In a democracy, political power ultimately belongs to:', ARRAY['The king', 'The armed forces', 'The people', 'The richest citizens'], 2, 'In a democracy, the people are the source of political power and exercise it through elections and participation.'),
  ('q_lit_001', 'Literature-in-English', 'Drama', 'The climax of a play is the point at which:', ARRAY['The play begins', 'The conflict reaches its highest point', 'The curtain falls', 'The audience leaves'], 1, 'The climax is the point of greatest tension in a story, where the main conflict reaches its peak.'),
  ('q_lit_002', 'Literature-in-English', 'Poetry', 'What is a poem''s rhyme scheme?', ARRAY['The number of stanzas', 'The pattern of rhymes at the end of lines', 'The length of each line', 'The use of commas'], 1, 'A rhyme scheme is the pattern formed by end rhymes in a poem, often shown with letters such as ABAB.'),
  ('q_lit_003', 'Literature-in-English', 'Prose', 'In prose fiction, a character who opposes the main character is called the:', ARRAY['Protagonist', 'Antagonist', 'Narrator', 'Bystander'], 1, 'The antagonist is the character who opposes or challenges the protagonist in a story.'),
  ('q_lit_004', 'Literature-in-English', 'Literary Devices', 'What is a metaphor?', ARRAY['A direct comparison using ''like'' or ''as''', 'A figure of speech that describes one thing as if it were another', 'A long speech by one character', 'A repeated line in a poem'], 1, 'A metaphor directly identifies one thing with another, for example ''time is a thief'', without using ''like'' or ''as''.'),
  ('q_lit_005', 'Literature-in-English', 'Drama', 'What is the main purpose of stage directions in a play script?', ARRAY['To list the actors'' names', 'To tell actors and the director how lines and actions should be performed', 'To explain the author''s biography', 'To count the number of scenes'], 1, 'Stage directions give instructions on movement, tone, setting, and action that are not spoken aloud.'),
  ('q_fm_001', 'Further Mathematics', 'Algebra', 'If f(x) = 2x + 3, what is f(4)?', ARRAY['5', '8', '11', '14'], 2, 'Substitute x = 4 into 2x + 3 to get 2(4) + 3 = 8 + 3 = 11.'),
  ('q_fm_002', 'Further Mathematics', 'Matrices', 'What is the order of a matrix with 3 rows and 2 columns?', ARRAY['2 × 3', '3 × 2', '3 + 2', '6'], 1, 'The order of a matrix is written as rows first, then columns, so 3 rows and 2 columns give the order 3 × 2.'),
  ('q_fm_003', 'Further Mathematics', 'Calculus', 'What is the derivative of x^2?', ARRAY['x', '2', '2x', 'x^2'], 2, 'Using the power rule, the derivative of x^2 is 2x^(2-1) = 2x.'),
  ('q_fm_004', 'Further Mathematics', 'Complex Numbers', 'The imaginary part of the complex number 3 + 4i is:', ARRAY['3', '4', '4i', '3 + 4i'], 1, 'In a + bi, the imaginary part is b, so the imaginary part of 3 + 4i is 4.'),
  ('q_fm_005', 'Further Mathematics', 'Geometry', 'What is the gradient of the line y = 5x - 2?', ARRAY['-2', '5', '2', '5x'], 1, 'In y = mx + c, the gradient is m, so the gradient of y = 5x - 2 is 5.');
